IntlWrapper::IntlWrapper( LanguageTag aLanguageTag )
        :
        maLanguageTag(std::move( aLanguageTag )),
        m_xContext( comphelper::getProcessComponentContext() )
{
}
#include <comphelper/processfactory.hxx>
